function detectLang(): Lang {
  try {
    const stored = localStorage.getItem('gestalt:lang')
    if (stored && allLangs.includes(stored as Lang)) return stored as Lang
  } catch { /* storage unavailable */ }
  const base = (navigator.language ?? 'en').split('-')[0] ?? ''
  return (allLangs as string[]).includes(base) ? (base as Lang) : 'en'
}

/** Signals keep the UI reactive everywhere t() is read from a template. */
let current = $state<Lang>(detectLang())

export function getLang(): Lang { return current }

export function setLang(lang: Lang): void {
  current = lang
  try { localStorage.setItem('gestalt:lang', lang) } catch { /* private mode */ }
}

export type Vars = Record<string, string | number>

/** Translate `key` in the current language, falling back to English, then to the raw key. */
export function t(key: string, vars?: Vars): string {
  let text = translations[current][key] ?? translations.en[key] ?? key
  if (vars) for (const [k, v] of Object.entries(vars)) text = text.replaceAll(`{${k}}`, String(v))
  return text
}
